import React from "react";
import type { Metadata } from "next";
import { Phone, CalendarCheck, Tag, Info } from "lucide-react";
import Breadcrumbs from "@/components/Breadcrumbs";
import { BookingModalTrigger } from "@/components/BookingModalProvider";
import BookingForm from "@/components/BookingForm";
import { getPromotions, getSiteSettings } from "@/lib/db-queries";

export const metadata: Metadata = {
  title: "Акции и специальные предложения",
  description:
    "Информация о специальных предложениях стоматологической клиники «Квалитет» в Москве. Уточнение действующих условий по телефону регистратуры.",
  alternates: {
    canonical: "/promotions",
  },
};

export default async function PromotionsPage() {
  const [promotions, settings] = await Promise.all([
    getPromotions(),
    getSiteSettings(),
  ]);

  return (
    <div className="mx-auto max-w-[1360px] px-4 py-10 sm:px-6 lg:px-8 lg:py-14 space-y-16">
      <div>
        <Breadcrumbs items={[{ label: "Акции" }]} />
        <div className="max-w-3xl space-y-3">
          <span className="text-xs font-semibold uppercase tracking-widest text-[#9A754D]">
            Специальные предложения • Квалитет
          </span>
          <h1 className="font-serif-editorial text-4xl font-semibold text-[#14221E] sm:text-5xl">
            Акции клиники «Квалитет»
          </h1>
          <p className="text-sm sm:text-base leading-relaxed text-[#525D59]">
            Актуальная информация о действующих специальных предложениях на
            стоматологические услуги для взрослых и детей.
          </p>
        </div>
      </div>

      {promotions.length > 0 ? (
        <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
          {promotions.map((promo) => (
            <article
              key={promo.id}
              className="flex flex-col justify-between overflow-hidden rounded-3xl border border-[#E6E3DC] bg-white shadow-2xs"
            >
              <div>
                <div className="relative h-56 w-full bg-[#F3F1EC]">
                  <img
                    src={promo.imageUrl}
                    alt={promo.title}
                    loading="lazy"
                    className="h-full w-full object-cover"
                  />
                  {promo.validUntil && (
                    <span className="absolute left-4 top-4 rounded-full bg-white/95 px-3.5 py-1 text-xs font-semibold text-[#164E43]">
                      Срок действия: {promo.validUntil}
                    </span>
                  )}
                </div>
                <div className="p-6 sm:p-8 space-y-3">
                  <h2 className="font-serif-editorial text-2xl sm:text-3xl font-semibold text-[#14221E]">
                    {promo.title}
                  </h2>
                  <p className="text-sm leading-relaxed text-[#525D59]">
                    {promo.shortDescription}
                  </p>
                  {promo.conditions && (
                    <div className="rounded-xl bg-[#FAF9F6] p-4 text-xs text-[#525D59] border border-[#E6E3DC]">
                      <strong className="text-[#14221E]">
                        Подробные условия:
                      </strong>{" "}
                      {promo.conditions}
                    </div>
                  )}
                </div>
              </div>
              <div className="px-6 pb-6 sm:px-8 sm:pb-8">
                <BookingModalTrigger
                  service={`Акция: ${promo.title}`}
                  className="inline-flex h-11 items-center justify-center gap-2 rounded-xl bg-[#164E43] px-6 text-xs sm:text-sm font-medium text-white hover:bg-[#0F3A31] transition"
                >
                  <CalendarCheck className="h-4 w-4" />
                  <span>Записаться по акции</span>
                </BookingModalTrigger>
              </div>
            </article>
          ))}
        </div>
      ) : (
        <section className="rounded-3xl border border-[#E6E3DC] bg-white p-8 sm:p-12 shadow-2xs">
          <div className="max-w-2xl space-y-5">
            <div className="inline-flex h-12 w-12 items-center justify-center rounded-2xl bg-[#ECF4F1] text-[#164E43]">
              <Tag className="h-6 w-6" />
            </div>
            <h2 className="font-serif-editorial text-2xl sm:text-3xl font-semibold text-[#14221E]">
              Уточнение информации о специальных предложениях
            </h2>
            <p className="text-sm sm:text-base leading-relaxed text-[#525D59]">
              На текущий момент на сайте не опубликованы специальные акционные
              предложения. Чтобы узнать о действующих условиях на комплексное
              лечение, гигиену или семейный приём, пожалуйста, позвоните
              администратору клиники «Квалитет» по одному из телефонов:
            </p>

            <div className="flex flex-wrap gap-3 tabular-nums pt-1">
              {settings.phones.map((ph) => (
                <a
                  key={ph.href}
                  href={ph.href}
                  className="inline-flex items-center gap-2 rounded-xl border border-[#E6E3DC] bg-[#FAF9F6] px-4 py-3 text-sm font-semibold text-[#14221E] hover:border-[#164E43] transition"
                >
                  <Phone className="h-4 w-4 text-[#164E43]" />
                  {ph.display}
                </a>
              ))}
            </div>

            <div className="flex items-start gap-2.5 rounded-xl bg-[#F3F1EC] p-4 text-xs text-[#525D59]">
              <Info className="h-4 w-4 shrink-0 text-[#164E43] mt-0.5" />
              <span>
                Мы не размещаем неподтверждённые скидки и рекламные обещания.
                Администратор клиники может публиковать и архивировать акции в
                любой момент через систему управления сайтом.
              </span>
            </div>
          </div>
        </section>
      )}

      <section className="rounded-3xl border border-[#E6E3DC] bg-white p-6 sm:p-10 shadow-2xs">
        <div className="max-w-3xl space-y-6">
          <h2 className="font-serif-editorial text-3xl font-semibold text-[#14221E]">
            Оставить заявку на консультацию
          </h2>
          <BookingForm />
        </div>
      </section>
    </div>
  );
}
